ln_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cooperative_groups.h>

#include <cute/tensor.hpp>

using namespace cute;
namespace cg = cooperative_groups;

constexpr int kThreads = 256;
constexpr int kVecCache = 4;
// Optimization: shrink the per-thread float4 X register cache from 8 to 4
// and raise __launch_bounds__ to 4 blocks/SM. Profiling shows the kernel is
// register-limited (80 regs/thread -> 50% theoretical occupancy, ~6 warps
// per scheduler vs 12 max). The smaller cache cuts register pressure so a
// 4th block fits per SM, improving latency hiding; grid size still comes
// from the occupancy query. Overflow beyond the cache uses the fallback loop.
__device__ __forceinline__ void warp_reduce2(double& a, double& b)
{
  for (int offset = 16; offset > 0; offset >>= 1) {
    a += __shfl_down_sync(0xffffffffu, a, offset);
    b += __shfl_down_sync(0xffffffffu, b, offset);
  }
}
__global__ void __launch_bounds__(kThreads, 4) layernorm_coop_kernel(const float* __restrict__ X,
                                      const float* __restrict__ W,
                                      const float* __restrict__ B,
                                      float* __restrict__ Y,
                                      double* __restrict__ partial,
                                      float* __restrict__ stats,
                                      int rows,
                                      int64_t row_len,
                                      float eps)
{
  constexpr int Threads = kThreads;
  const int tid = threadIdx.x;
  const int bid = blockIdx.x;
  const int nblocks = gridDim.x;
  const int gtid = bid * Threads + tid;
  const int stride = nblocks * Threads;
  const int row_len_i = (int)row_len; const int nvec = row_len_i >> 2;
  const int tail_begin = nvec << 2;
  const float4* __restrict__ X4 = reinterpret_cast<const float4*>(X);
  const float4* __restrict__ W4 = reinterpret_cast<const float4*>(W);
  const float4* __restrict__ B4 = reinterpret_cast<const float4*>(B);
  float4* __restrict__ Y4 = reinterpret_cast<float4*>(Y);
  __shared__ double s_sum[Threads];
  __shared__ double s_sumsq[Threads];
  cg::grid_group grid = cg::this_grid();
  for (int r = 0; r < rows; ++r) {
    const int parity = r & 1;
    double* part_sum = partial + (int64_t)parity * 2 * (int64_t)nblocks;
    double* part_sumsq = part_sum + nblocks;
    const float4* __restrict__ xrow4 = X4 + r * nvec;
    const float4* __restrict__ xend4 = xrow4 + nvec;
    const float* __restrict__ xrow = X + r * row_len_i;
    float4* __restrict__ yrow4 = Y4 + r * nvec;
    float* __restrict__ yrow = Y + r * row_len_i;
    double local_sum = 0.0;
    double local_sumsq = 0.0;
    float4 xcache[kVecCache];
#pragma unroll
    for (int k = 0; k < kVecCache; ++k) {
        const int idx = gtid + k * stride;
      if (idx < nvec) {
        float4 xv = xrow4[idx];
        xcache[k] = xv;
        double x0 = (double)xv.x;
        double x1 = (double)xv.y;
        double x2 = (double)xv.z;
        double x3 = (double)xv.w;
        local_sum   += x0 + x1 + x2 + x3;
        local_sumsq += x0*x0 + x1*x1 + x2*x2 + x3*x3;
      }
    }
    #pragma unroll 2
    for (const float4* p = xrow4 + (gtid + kVecCache * stride); p < xend4; p += stride) {
      float4 xv = *p;
      double x0 = (double)xv.x;
      double x1 = (double)xv.y;
      double x2 = (double)xv.z;
      double x3 = (double)xv.w;
      local_sum   += x0 + x1 + x2 + x3;
      local_sumsq += x0*x0 + x1*x1 + x2*x2 + x3*x3;
    }
    for (int i = tail_begin + gtid; i < row_len_i; i += stride) {
      double x0 = (double)xrow[i];
      local_sum += x0;
      local_sumsq += x0 * x0;
    }
    const int lane = tid & 31;
    const int warp = tid >> 5;
    constexpr int Warps = Threads / 32;
    warp_reduce2(local_sum, local_sumsq);
    if (lane == 0) {
      s_sum[warp] = local_sum;
      s_sumsq[warp] = local_sumsq;
    }
    __syncthreads();
    if (warp == 0) {
      double a = (lane < Warps) ? s_sum[lane] : 0.0;
      double b = (lane < Warps) ? s_sumsq[lane] : 0.0;
      warp_reduce2(a, b);
      if (lane == 0) {
        part_sum[bid] = a;
        part_sumsq[bid] = b;
      }
    }
    grid.sync();
    double block_sum = 0.0;
    double block_sumsq = 0.0;
    for (int b = tid; b < nblocks; b += Threads) {
      block_sum += part_sum[b];
      block_sumsq += part_sumsq[b];
    }
    warp_reduce2(block_sum, block_sumsq);
    if (lane == 0) {
      s_sum[warp] = block_sum;
      s_sumsq[warp] = block_sumsq;
    }
    __syncthreads();
    if (warp == 0) {
      double a = (lane < Warps) ? s_sum[lane] : 0.0;
      double b = (lane < Warps) ? s_sumsq[lane] : 0.0;
      warp_reduce2(a, b);
      if (lane == 0) {
        s_sum[0] = a;
        s_sumsq[0] = b;
      }
    }
    __syncthreads();
    const double total_sum = s_sum[0];
    const double total_sumsq = s_sumsq[0];
    double mean_d = total_sum / (double)row_len;
    double var_d = total_sumsq / (double)row_len - mean_d * mean_d;
    if (var_d < 0.0) var_d = 0.0;
    double rstd_d = rsqrt(var_d + (double)eps);
    if (bid == 0 && tid == 0) {
      stats[0] = (float)mean_d;
      stats[1] = (float)rstd_d;
    }
    const float mean = (float)mean_d;
    const float rstd = (float)rstd_d;
#pragma unroll
    for (int k = 0; k < kVecCache; ++k) {
      const int idx = gtid + k * stride;
      if (idx < nvec) {
        float4 xv = xcache[k];
        float4 wv = W4[idx];
        float4 bv = B4[idx];
        float4 yv;
        yv.x = (xv.x - mean) * rstd * wv.x + bv.x;
        yv.y = (xv.y - mean) * rstd * wv.y + bv.y;
        yv.z = (xv.z - mean) * rstd * wv.z + bv.z;
        yv.w = (xv.w - mean) * rstd * wv.w + bv.w;
        yrow4[idx] = yv;
      }
    }
    #pragma unroll 2
    for (int idx = gtid + kVecCache * stride; idx < nvec; idx += stride) {
      float4 xv = xrow4[idx];
      float4 wv = W4[idx];
      float4 bv = B4[idx];
      float4 yv;
      yv.x = (xv.x - mean) * rstd * wv.x + bv.x;
      yv.y = (xv.y - mean) * rstd * wv.y + bv.y;
      yv.z = (xv.z - mean) * rstd * wv.z + bv.z;
      yv.w = (xv.w - mean) * rstd * wv.w + bv.w;
      yrow4[idx] = yv;
    }
    for (int i = tail_begin + gtid; i < row_len_i; i += stride) {
      float x0 = xrow[i];
      yrow[i] = (x0 - mean) * rstd * W[i] + B[i];
    }
  }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat && bias.scalar_type() == at::kFloat,
              "weight/bias must be float32");
  TORCH_CHECK(weight.dim() >= 1, "weight must have at least one dim");
  TORCH_CHECK(weight.sizes() == bias.sizes(), "weight and bias shapes must match");
  TORCH_CHECK(x.dim() >= weight.dim(), "x must have trailing normalized_shape dims");

  for (int i = 0; i < weight.dim(); ++i) {
    TORCH_CHECK(x.size(x.dim() - weight.dim() + i) == weight.size(i),
                "x trailing shape must match normalized_shape");
  }

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();

  const int64_t row_len = w_c.numel();
  TORCH_CHECK(row_len > 0, "normalized_shape must be non-empty");
  TORCH_CHECK(x_c.numel() % row_len == 0 && row_len <= (int64_t)2147483647 && x_c.numel() <= (int64_t)2147483647, "x numel must be divisible by normalized numel and fit int32 indexing");
  const int rows = (int)(x_c.numel() / row_len);

  auto y = torch::empty_like(x_c);
  if (rows == 0) {
    return y;
  }

  constexpr int Threads = 256;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  int dev = 0;
  cudaGetDevice(&dev);
  int supports_coop = 0;
  cudaDeviceGetAttribute(&supports_coop, cudaDevAttrCooperativeLaunch, dev);
  TORCH_CHECK(supports_coop, "Device does not support cooperative launch");

  void* kernel_ptr = (void*)(&layernorm_coop_kernel);
  int blocks_per_sm = 0;
  auto occ_err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm,
                                                               (const void*)kernel_ptr,
                                                               Threads,
                                                               0);
  TORCH_CHECK(occ_err == cudaSuccess, "Occupancy query failed: ", cudaGetErrorString(occ_err));
  TORCH_CHECK(blocks_per_sm > 0, "Invalid occupancy for layernorm kernel");

  cudaDeviceProp prop;
  cudaGetDeviceProperties(&prop, dev);
  int nblocks = blocks_per_sm * prop.multiProcessorCount;
  TORCH_CHECK(nblocks > 0, "Invalid cooperative grid size");

  auto dopts = torch::TensorOptions().dtype(torch::kFloat64).device(x.device());
  auto fopts = torch::TensorOptions().dtype(torch::kFloat32).device(x.device());
  auto partial = torch::empty({(int64_t)nblocks * 4}, dopts);
  auto stats = torch::empty({2}, fopts);

  const float* x_ptr = x_c.data_ptr<float>();
  const float* w_ptr = w_c.data_ptr<float>();
  const float* b_ptr = b_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();
  double* partial_ptr = partial.data_ptr<double>();
  float* stats_ptr = stats.data_ptr<float>();
  float eps_f = (float)eps;
  int rows_arg = rows;
  int64_t row_len_arg = row_len;

  void* args[] = {
    (void*)&x_ptr,
    (void*)&w_ptr,
    (void*)&b_ptr,
    (void*)&y_ptr,
    (void*)&partial_ptr,
    (void*)&stats_ptr,
    (void*)&rows_arg,
    (void*)&row_len_arg,
    (void*)&eps_f
  };

  auto launch_err = cudaLaunchCooperativeKernel((const void*)kernel_ptr,
                                                dim3(nblocks),
                                                dim3(Threads),
                                                args,
                                                0,
                                                stream);
  TORCH_CHECK(launch_err == cudaSuccess, "Cooperative LayerNorm launch failed: ",
              cudaGetErrorString(launch_err));

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE LayerNorm kernel failed: ", cudaGetErrorString(err));

  return y;
}
"""

ln_ext = load_inline(
    name="cute_layernorm_coop_ext",
    cpp_sources=ln_cpp_decl,
    cuda_sources=ln_cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single cooperative CUDA/CuTe kernel.
    Keeps nn.LayerNorm parameters for identical initialization/state_dict naming,
    but forward() uses only the custom kernel for computation.
    """
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.ln = nn.LayerNorm(normalized_shape=self.normalized_shape)
        self._ext = ln_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.ln.weight,
            self.ln.bias,
            float(self.ln.eps),
        ).view_as(x)

