  TORCH_CHECK(weight.scalar_type() == at::kFloat && bias.scalar_type() == at::kFloat,
              "weight/bias must be float32");
  TORCH_CHECK(weight.dim() >= 1, "weight must have at least one dim");
  TORCH_CHECK(weight.sizes() == bias.sizes(), "weight and bias shapes must match");
  TORCH_CHECK(x.dim() >= weight.dim(), "x must have trailing normalized_shape dims");

  for (int i = 0; i < weight.dim(); ++i) {
    TORCH_CHECK(x.size(x.dim() - weight.dim() + i) == weight.size(i),
                "x trailing shape must match normalized_shape");
  }

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();

  const int64_t row_len = w_c.numel();
  TORCH_CHECK(row_len > 0, "normalized_shape must be non-empty");
  TORCH_CHECK(x_c.numel() % row_len == 0, "x numel must be divisible by normalized numel");
  const int rows = (int)(x_c.numel() / row_len);

  auto y = torch::empty_like(x_c);
  if (rows == 0) {
    return y;
  }

  constexpr int Threads = 256;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  int dev = 0;
  cudaGetDevice(&dev);
  int supports_coop = 0;
  cudaDeviceGetAttribute(&supports_coop, cudaDevAttrCooperativeLaunch, dev);
  TORCH_CHECK(supports_coop, "Device does not support cooperative launch");

  void* kernel_ptr = (void*)(&layernorm_coop_kernel);
  int blocks_per_sm = 0;
  auto occ_err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm,
                                                               (const void*)kernel_ptr,
                                                               Threads,
                                                               0);
  TORCH_CHECK(occ_err == cudaSuccess, "Occupancy query failed: ", cudaGetErrorString(occ_err));
  TORCH_CHECK(blocks_per_sm > 0, "Invalid occupancy for layernorm kernel");

  cudaDeviceProp prop;
  cudaGetDeviceProperties(&prop, dev);
  int nblocks = blocks_per_sm * prop.multiProcessorCount;
  TORCH_CHECK(nblocks > 0, "Invalid cooperative grid size");

  auto dopts = torch::TensorOptions().dtype(torch::kFloat64).device(x.device());
  auto fopts = torch::TensorOptions().dtype(torch::kFloat32).device(x.device());
  auto partial = torch::empty({(int64_t)nblocks * 4}, dopts);
  auto stats = torch::empty({2}, fopts);

  const float* x_ptr = x_c.data_ptr<float>();
  const float* w_ptr = w_c.data_ptr<float>();
  const float* b_ptr = b_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();
  double* partial_ptr = partial.data_ptr<double>();
  float* stats_ptr = stats.data_ptr<float>();
  float eps_f = (float)eps;
  int rows_arg = rows;
  int64_t row_len_arg = row_len;

  void* args[] = {
    (void*)&x_ptr,
    (void*)&w_ptr,
    (void*)&b_ptr,
    (void*)&y_ptr,
    (void*)&partial_ptr,
    (void*)&stats_ptr,
    (void*)&rows_arg,
    (void*)&row_len_arg,
    (void*)&eps_f
  };

  auto launch_err = cudaLaunchCooperativeKernel((const void*)kernel_ptr,
                                                dim3(nblocks),
                                                dim3(Threads),
                                                args,
                                                0,
                                                stream);
  TORCH_CHECK(launch_err == cudaSuccess, "Cooperative LayerNorm launch failed: ",
              cudaGetErrorString(launch_err));

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE LayerNorm kernel failed: ", cudaGetErrorString(err));

  return y;
}
